#The measure's latest spcPoints recorded events (each a minute or so of samples' average) and the SPC check of them
#against its configured limits: the same check the UDT's update script writes to outOfControl / ruleViolations
#(868mtrbyg). Refreshes each time an event is recorded (lastUpdated)
#Given a startDate and endDate (the Production Counts summary's SPC Alerts link), the events in that range instead, as the
#summary counted its alerts
tagPath = value['tagPath']
if not tagPath: return {'points': [], 'violationPoints': [], 'violations': [], 'outOfControl': False, 'limits': {}}
names = ['measureId', 'spcPoints', 'spcCheckEnabled', 'spec/lsl', 'spec/lcl', 'spec/tgt', 'spec/ucl', 'spec/usl']
vals = [q.value for q in system.tag.readBlocking([tagPath + '/' + n for n in names])]
measureId, spcPoints, enabled, lsl, lcl, tgt, ucl, usl = vals
limits = {'lsl': lsl, 'lcl': lcl, 'tgt': tgt, 'ucl': ucl, 'usl': usl}
given = value['range'] or {}
start, end = given.get('startDate'), given.get('endDate')
if start is not None and end is not None:
	events = system.kanoa.measures.getMeasureEvents({'measureId': measureId, 'tStampStart': start, 'tStampEnd': end, 'maxRows': 0})
else:
	events = system.kanoa.measures.getMeasureEvents({'measureId': measureId, 'maxRows': spcPoints or 30})
points = []
if hasattr(events, 'getRowCount'):
	for i in range(events.rowCount):
		if events.getValueAt(i, 'measureValue') is not None:
			points.append({'time': events.getValueAt(i, 'tStamp'), 'value': events.getValueAt(i, 'measureValue')})
result = {'points': points, 'violationPoints': [], 'violations': [], 'outOfControl': False, 'limits': limits}
if enabled and len(points) >= 2:
	info = system.kanoa.quality.spc.spcCheck([pt['value'] for pt in points], 'individuals', 'both', None, usl, lsl, None, ucl, lcl, tgt)
	if isinstance(info, dict):
		#Each point in a violating run, with the most serious kind of rule it breaks (as the legend colours them)
		ruleInfo = system.kanoa.quality.spc.getRuleInfo()
		if not isinstance(ruleInfo, dict): ruleInfo = {}
		rank = {'limit': 3, 'pattern': 2, 'variation': 1}
		kinds = {}
		for rule, indexes in info['violationPoints'].items():
			kind = (ruleInfo.get(rule) or {}).get('kind') or 'pattern'
			for i in indexes:
				if rank.get(kind, 0) > rank.get(kinds.get(i), 0): kinds[i] = kind
		result['violationPoints'] = [{'index': i, 'kind': kinds[i]} for i in sorted(kinds)]
		result['violations'] = list(info['violations'].keys())
		result['outOfControl'] = bool(info['outOfControl'])
return result

#Limit lines from the measure's spec, and the y axis over every value shown
spc = value['spc'] or {}
limits = spc.get('limits') or {}
lsl, lcl, tgt, ucl, usl = [limits.get(k) for k in ('lsl', 'lcl', 'tgt', 'ucl', 'usl')]
valueList = []
for s in value['series'] or []:
	valueList += [pt[k] for pt in s['data'] for k in pt.keys() if k != 'time' and pt[k] is not None]
if not valueList: return []

allVals = valueList + [v for v in [lsl, lcl, tgt, ucl, usl] if v is not None]
minRange = min(allVals)
maxRange = max(allVals)
padding = (maxRange - minRange) * 0.1 if maxRange != minRange else 1.0

def buildMarker(name, val, color, dashArray, position):
	return {
		'visible': True,
		'type': 'line',
		'axis': 'Axis1',
		'value': val,
		'line': {
			'color': color,
			'width': 1,
			'opacity': 0.8,
			'dashArray': dashArray,
			'label': {
				'text': name,
				'position': position,
				'font': {'color': '', 'size': 10},
				'style': {'classes': ''}
			}
		}
	}

markers = []
if lsl is not None: markers.append(buildMarker('LSL', lsl, '#FF0000', 0, 'left'))
if lcl is not None: markers.append(buildMarker('LCL', lcl, '#FF8C00', '5.5', 'left'))
if tgt is not None: markers.append(buildMarker('Target', tgt, '#00AC00', 0, 'left'))
if ucl is not None: markers.append(buildMarker('UCL', ucl, '#FF8C00', '5.5', 'right'))
if usl is not None: markers.append(buildMarker('USL', usl, '#FF0000', 0, 'right'))

#Each series' value key, as custom.timeSeries.series names it (the hover shows it)
keys = {'Recorded': 'Value', 'Current samples': 'Current sample'}
def trend(series, kind, radius, color):
	return {'visible': True, 'type': kind, 'series': series, 'interpolation': 'curveLinear', 'breakLine': True, 'stack': False,
			'radius': radius, 'axis': 'Axis1', 'columns': [{'key': keys.get(series, series), 'color': color}], 'baselines': []}

#Dots sized to how many points there are, so a day or a week of them (the Production Counts summary's range) doesn't run
#together; a point in a violation stays bigger than a recorded one
count = sum([len(s['data']) for s in value['series'] or [] if s['name'] == 'Recorded'])
if count <= 60: dot, flagged = 3, 6
elif count <= 300: dot, flagged = 2, 4
elif count <= 1500: dot, flagged = 1, 3
else: dot, flagged = 0, 2

#A trend for each series that has points (the violations in the legend's colours), drawn in this order
shown = [s['name'] for s in value['series'] or []]
trends = [trend(name, kind, radius, color) for name, kind, radius, color in [
	('Current samples', 'line', 0, '#9E9E9E'), ('Recorded', 'line', dot, '#7B1FA2'),
	('Too little variation', 'scatter', flagged, 'var(--kcBlue-50)'), ('Shift or drift pattern', 'scatter', flagged, 'var(--kcOrange-50)'),
	('Beyond a limit', 'scatter', flagged, 'var(--kcRed-50)')] if name in shown]

return [{
	'trends': trends,
	'axes': [{
		'name': 'Axis1',
		'min': minRange - padding,
		'max': maxRange + padding,
		#One axis, on the left: every series is the measure's value, so they share its range
		'alignment': 'left',
		'width': 60,
		'label': {'visible': False, 'text': 'Value', 'offset': 1, 'font': {'color': '', 'size': 10}, 'style': {'classes': ''}},
		'tick': {'color': '', 'label': {'font': {'color': '', 'size': 10}, 'style': {'classes': ''}}, 'style': {'classes': ''}},
		'style': {'classes': ''}
	}],
	'markers': markers
}]

#Recorded events, the points among them in a violating run, and the samples still being collected for the next event
spc = value['spc'] or {}
recorded = [{'time': pt['time'], 'value': pt['value']} for pt in (spc.get('points') or [])]
byKind = {'limit': [], 'pattern': [], 'variation': []}
for point in spc.get('violationPoints') or []:
	if point['index'] < len(recorded): byKind.setdefault(point['kind'], []).append(recorded[point['index']])
live = []
if value['live'] is not None:
	live = [{'time': row['tStamp'], 'value': row['value']} for row in system.dataset.toPyDataSet(value['live']) if row['value'] is not None]
series = [{'name': 'Recorded', 'data': recorded}, {'name': 'Beyond a limit', 'data': byKind['limit']},
		  {'name': 'Shift or drift pattern', 'data': byKind['pattern']}, {'name': 'Too little variation', 'data': byKind['variation']},
		  {'name': 'Current samples', 'data': live}]
#Each series' value under a key of its own, which the chart's hover shows as its name (all of them under 'value' showed
#"value" on every line)
keys = {'Recorded': 'Value', 'Current samples': 'Current sample'}
for s in series:
	key = keys.get(s['name'], s['name'])
	s['data'] = [{'time': pt['time'], key: pt['value']} for pt in s['data']]
#Only the series with points: the chart gives an empty one an axis of its own
return [s for s in series if s['data']]

#Each rule the check flagged as a pill: its readable name, what it means, and a colour for its kind (868mtrbyg)
COLORS = {'limit': '--kcRed-50', 'pattern': '--kcOrange-50', 'variation': '--kcBlue-50'}
info = system.kanoa.quality.spc.getRuleInfo()
if not isinstance(info, dict): info = {}
pills = []
for rule in value or []:
	r = info.get(rule) or {'label': rule, 'description': rule, 'kind': 'pattern'}
	pills.append({'label': r['label'], 'description': r['description'], 'color': COLORS.get(r['kind'], '--kcOrange-50')})
return pills
